CREATE TABLE public.profiles (id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE, display_name text NOT NULL DEFAULT '' CHECK (length(display_name) <= 100), created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, UPDATE ON public.profiles TO authenticated; GRANT ALL ON public.profiles TO service_role;
ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.companies (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL CHECK (length(name) BETWEEN 1 AND 150));
GRANT SELECT ON public.companies TO authenticated; GRANT ALL ON public.companies TO service_role;
ALTER TABLE public.companies ENABLE ROW LEVEL SECURITY;
CREATE TYPE public.app_role AS ENUM ('trainee','hr');
CREATE TABLE public.user_roles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, role public.app_role NOT NULL, UNIQUE(user_id,role));
GRANT SELECT ON public.user_roles TO authenticated; GRANT ALL ON public.user_roles TO service_role;
ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.company_members (user_id uuid PRIMARY KEY, company_id uuid NOT NULL REFERENCES public.companies(id));
GRANT SELECT ON public.company_members TO authenticated; GRANT ALL ON public.company_members TO service_role;
ALTER TABLE public.company_members ENABLE ROW LEVEL SECURITY;
CREATE FUNCTION public.can_view_trainee(target uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$ SELECT auth.uid() = target OR EXISTS (SELECT 1 FROM public.user_roles r JOIN public.company_members h ON h.user_id=r.user_id JOIN public.company_members t ON t.company_id=h.company_id WHERE r.user_id=auth.uid() AND r.role='hr' AND t.user_id=target) $$;
REVOKE ALL ON FUNCTION public.can_view_trainee(uuid) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.can_view_trainee(uuid) TO authenticated;
CREATE POLICY own_or_company_profiles ON public.profiles FOR SELECT TO authenticated USING (public.can_view_trainee(id));
CREATE POLICY own_profile_update ON public.profiles FOR UPDATE TO authenticated USING (id=auth.uid()) WITH CHECK(id=auth.uid());
CREATE POLICY own_roles ON public.user_roles FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE POLICY visible_members ON public.company_members FOR SELECT TO authenticated USING(public.can_view_trainee(user_id));
CREATE POLICY own_company ON public.companies FOR SELECT TO authenticated USING(EXISTS(SELECT 1 FROM public.company_members WHERE user_id=auth.uid() AND company_id=companies.id));
CREATE TABLE public.workout_logs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL DEFAULT auth.uid(), title text NOT NULL CHECK(length(title) BETWEEN 1 AND 120), duration_minutes integer NOT NULL CHECK(duration_minutes BETWEEN 1 AND 600), completed boolean NOT NULL DEFAULT false, workout_date date NOT NULL DEFAULT current_date, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.workout_logs TO authenticated; GRANT ALL ON public.workout_logs TO service_role;
ALTER TABLE public.workout_logs ENABLE ROW LEVEL SECURITY;
CREATE POLICY visible_workouts ON public.workout_logs FOR SELECT TO authenticated USING(public.can_view_trainee(user_id));
CREATE POLICY own_workouts ON public.workout_logs FOR ALL TO authenticated USING(user_id=auth.uid()) WITH CHECK(user_id=auth.uid());
CREATE TABLE public.fitness_entries (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL DEFAULT auth.uid(), entry_date date NOT NULL DEFAULT current_date, weight_kg numeric NOT NULL CHECK(weight_kg BETWEEN 20 AND 350), height_cm numeric NOT NULL CHECK(height_cm BETWEEN 100 AND 250), calories integer NOT NULL CHECK(calories BETWEEN 0 AND 20000), created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(user_id,entry_date));
GRANT SELECT,INSERT,UPDATE,DELETE ON public.fitness_entries TO authenticated; GRANT ALL ON public.fitness_entries TO service_role;
ALTER TABLE public.fitness_entries ENABLE ROW LEVEL SECURITY;
CREATE POLICY visible_fitness ON public.fitness_entries FOR SELECT TO authenticated USING(public.can_view_trainee(user_id));
CREATE POLICY own_fitness ON public.fitness_entries FOR ALL TO authenticated USING(user_id=auth.uid()) WITH CHECK(user_id=auth.uid());
CREATE FUNCTION public.create_client_profile() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN INSERT INTO public.profiles(id,display_name) VALUES(NEW.id,left(coalesce(NEW.raw_user_meta_data->>'display_name',''),100)); INSERT INTO public.user_roles(user_id,role) VALUES(NEW.id,'trainee'); RETURN NEW; END; $$;
CREATE TRIGGER on_client_signup AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION public.create_client_profile();
INSERT INTO public.profiles(id,display_name) SELECT id,left(coalesce(raw_user_meta_data->>'display_name',''),100) FROM auth.users ON CONFLICT DO NOTHING;
INSERT INTO public.user_roles(user_id,role) SELECT id,'trainee'::public.app_role FROM auth.users ON CONFLICT DO NOTHING;